#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include "tvm_ffi_utils.h"
using tvm::ffi::TensorView;

template <typename T>
__global__ void _rmsnorm_kernel(const T* __restrict__ x, const T* __restrict__ w,
                                T* __restrict__ out, int hidden, float eps) {
  int row = blockIdx.x;
  const T* xr = x + (long long)row * hidden;
  T* outr = out + (long long)row * hidden;
  float local = 0.f;
  for (int i = threadIdx.x; i < hidden; i += blockDim.x) {
    float v = static_cast<float>(xr[i]);
    local += v * v;
  }
  for (int off = 16; off > 0; off >>= 1)
    local += __shfl_down_sync(0xffffffffu, local, off);
  __shared__ float ssum[32];
  int warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
  if (lane == 0) ssum[warp] = local;
  __syncthreads();
  if (threadIdx.x == 0) {
    float total = 0.f;
    int nwarps = (blockDim.x + 31) >> 5;
    for (int i = 0; i < nwarps; ++i) total += ssum[i];
    ssum[0] = rsqrtf(total / hidden + eps);
  }
  __syncthreads();
  float rinv = ssum[0];
  for (int i = threadIdx.x; i < hidden; i += blockDim.x) {
    outr[i] = static_cast<T>((static_cast<float>(xr[i]) * rinv) * static_cast<float>(w[i]));
  }
}

void rmsnorm_cuda(TensorView input, TensorView weight, TensorView output) {
  int batch = input.size(0);
  int hidden = input.size(1);
  ffi::CUDADeviceGuard guard(input.device().device_id);
  cudaStream_t stream = get_stream(input.device());
  int threads = 256;
  DISPATCH_DLPACK_DTYPE_TO_CTYPE_FP16(input.dtype(), c_type, [&] {
    _rmsnorm_kernel<c_type><<<batch, threads, 0, stream>>>(
        static_cast<const c_type*>(input.data_ptr()),
        static_cast<const c_type*>(weight.data_ptr()),
        static_cast<c_type*>(output.data_ptr()), hidden, 1e-6f);
    return true;
  });
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(rmsnorm_cuda, rmsnorm_cuda);
